content:
Use a single reusable environment module, but keep one Terraform state per environment. A root module that iterates over both `dev` and `prod` would remove duplication but violate the requirement that prod changes cannot affect dev state.

## Layout

```text
terraform/
├── modules/
│   └── environment/
│       ├── main.tf
│       ├── variables.tf
│       └── outputs.tf
├── main.tf
├── variables.tf
├── dev.tfvars
├── prod.tfvars
└── moves.tf
```

## Root module

### `main.tf`

Each state supplies a singleton environment map, so the same configuration uses `for_each` while preserving state isolation.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }

  backend "s3" {}
}

provider "aws" {
  region = var.region
}

provider "aws" {
  alias  = "replica"
  region = "us-west-2"
}

module "environment" {
  for_each = var.environments

  source = "./modules/environment"

  providers = {
    aws         = aws
    aws.replica = aws.replica
  }

  environment = each.key
  region      = each.value.region

  node_instance_type = each.value.node_instance_type
  node_count         = each.value.node_count

  db_instance_class = each.value.db_instance_class
  db_multi_az       = each.value.db_multi_az
  db_encrypted      = each.value.db_encrypted

  enable_replication = each.value.enable_replication
  enable_cloudfront  = each.value.enable_cloudfront

  db_connection_string = var.db_connection_string
}
```

### `variables.tf`

```hcl
variable "region" {
  type = string
}

variable "environments" {
  type = map(object({
    region             = string
    node_instance_type = string
    node_count         = number
    db_instance_class  = string
    db_multi_az        = bool
    db_encrypted       = bool
    enable_replication = bool
    enable_cloudfront  = bool
  }))

  validation {
    condition     = length(var.environments) == 1
    error_message = "Each state must manage exactly one environment."
  }
}

variable "db_connection_string" {
  type      = string
  sensitive = true
}
```

Do not commit the DB connection string to either tfvars file. Supply it through an encrypted CI secret, `TF_VAR_db_connection_string`, or decrypt a SOPS file outside Git plaintext handling. Note that sensitive Terraform values can still be stored in state, so the backend must be encrypted and access-controlled.

## Environment values

### `dev.tfvars`

```hcl
region = "us-east-1"

environments = {
  dev = {
    region             = "us-east-1"
    node_instance_type = "t3.medium"
    node_count         = 2
    db_instance_class  = "db.t3.micro"
    db_multi_az        = false
    db_encrypted       = false
    enable_replication = false
    enable_cloudfront  = false
  }
}
```

### `prod.tfvars`

```hcl
region = "us-east-2"

environments = {
  prod = {
    region             = "us-east-2"
    node_instance_type = "t3.large"
    node_count         = 4
    db_instance_class  = "db.t3.medium"
    db_multi_az        = true
    db_encrypted       = true
    enable_replication = true
    enable_cloudfront  = true
  }
}
```

Use separate backend keys:

```bash
terraform init \
  -backend-config="bucket=company-terraform-state" \
  -backend-config="key=web/dev.tfstate" \
  -backend-config="region=us-east-1"
```

and:

```bash
terraform init \
  -backend-config="bucket=company-terraform-state" \
  -backend-config="key=web/prod.tfstate" \
  -backend-config="region=us-east-1"
```

Workspaces are also possible, but distinct backend keys provide clearer isolation.

## Reusable module

### `modules/environment/variables.tf`

```hcl
terraform {
  required_providers {
    aws = {
      source                = "hashicorp/aws"
      configuration_aliases = [aws.replica]
    }
  }
}

variable "environment" {
  type = string
}

variable "region" {
  type = string
}

variable "node_instance_type" {
  type = string
}

variable "node_count" {
  type = number
}

variable "db_instance_class" {
  type = string
}

variable "db_multi_az" {
  type = bool
}

variable "db_encrypted" {
  type = bool
}

variable "enable_replication" {
  type = bool
}

variable "enable_cloudfront" {
  type = bool
}

variable "db_connection_string" {
  type      = string
  sensitive = true
}
```

Resources should retain their existing arguments exactly during the move. For example, if the previous blocks were named `aws_s3_bucket.assets_dev` and `aws_s3_bucket.assets_prod`, both become one block named `assets`:

```hcl
resource "aws_s3_bucket" "assets" {
  bucket = "application-assets-${var.environment}"

  tags = {
    Environment = var.environment
  }
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket = aws_s3_bucket.assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_eks_node_group" "application" {
  # Existing cluster, subnet, role, and lifecycle arguments remain unchanged.

  cluster_name    = aws_eks_cluster.this.name
  node_group_name = "${var.environment}-application"
  node_role_arn   = aws_iam_role.node.arn
  subnet_ids      = var.private_subnet_ids

  instance_types = [var.node_instance_type]

  scaling_config {
    desired_size = var.node_count
    min_size     = var.node_count
    max_size     = var.node_count
  }
}

resource "aws_db_instance" "postgres" {
  # Existing identifier, engine, subnet group, and security group arguments
  # must remain unchanged during the move.

  instance_class        = var.db_instance_class
  multi_az              = var.db_multi_az
  storage_encrypted     = var.db_encrypted
  deletion_protection   = true
  backup_retention_period = 7
  publicly_accessible   = false
}
```

Avoid changing names, tags, defaults, generated policies, or provider versions in the same change as the state-address refactor.

## Declarative state moves

`moved` blocks cannot use `for_each`; every old address must have an explicit move.

If dev and prod already have separate state files, place the relevant environment’s moves in `moves.tf`.

### Dev state

```hcl
moved {
  from = aws_eks_cluster.dev
  to   = module.environment["dev"].aws_eks_cluster.this
}

moved {
  from = aws_eks_node_group.dev
  to   = module.environment["dev"].aws_eks_node_group.application
}

moved {
  from = aws_s3_bucket.assets_dev
  to   = module.environment["dev"].aws_s3_bucket.assets
}

moved {
  from = aws_s3_bucket_versioning.assets_dev
  to   = module.environment["dev"].aws_s3_bucket_versioning.assets
}

moved {
  from = aws_s3_bucket_server_side_encryption_configuration.assets_dev
  to   = module.environment["dev"].aws_s3_bucket_server_side_encryption_configuration.assets
}

moved {
  from = aws_s3_bucket_public_access_block.assets_dev
  to   = module.environment["dev"].aws_s3_bucket_public_access_block.assets
}

moved {
  from = aws_db_instance.postgres_dev
  to   = module.environment["dev"].aws_db_instance.postgres
}

moved {
  from = aws_iam_user.service_dev
  to   = module.environment["dev"].aws_iam_user.service
}

moved {
  from = aws_iam_role.service_dev
  to   = module.environment["dev"].aws_iam_role.service
}
```

The prod file uses the corresponding addresses:

```hcl
moved {
  from = aws_eks_cluster.prod
  to   = module.environment["prod"].aws_eks_cluster.this
}

moved {
  from = aws_eks_node_group.prod
  to   = module.environment["prod"].aws_eks_node_group.application
}

moved {
  from = aws_s3_bucket.assets_prod
  to   = module.environment["prod"].aws_s3_bucket.assets
}

moved {
  from = aws_s3_bucket_versioning.assets_prod
  to   = module.environment["prod"].aws_s3_bucket_versioning.assets
}

moved {
  from = aws_s3_bucket_server_side_encryption_configuration.assets_prod
  to   = module.environment["prod"].aws_s3_bucket_server_side_encryption_configuration.assets
}

moved {
  from = aws_s3_bucket_public_access_block.assets_prod
  to   = module.environment["prod"].aws_s3_bucket_public_access_block.assets
}

moved {
  from = aws_db_instance.postgres_prod
  to   = module.environment["prod"].aws_db_instance.postgres
}

moved {
  from = aws_iam_user.service_prod
  to   = module.environment["prod"].aws_iam_user.service
}

moved {
  from = aws_iam_role.service_prod
  to   = module.environment["prod"].aws_iam_role.service
}
```

Repeat this for every resource and data/resource instance in the duplicated blocks. Resources created with `count` or `for_each` must retain their instance key:

```hcl
moved {
  from = aws_subnet.private_dev[0]
  to   = module.environment["dev"].aws_subnet.private[0]
}

moved {
  from = aws_route_table_association.private_prod["us-east-2a"]
  to   = module.environment["prod"].aws_route_table_association.private["us-east-2a"]
}
```

## If dev and prod currently share one state

Splitting them into independently deployable state files cannot be done with `moved` blocks alone because `moved` only changes addresses inside one state. Use a staged migration:

1. Back up the existing state.
2. Refactor both environments to module addresses in the existing state using `moved` blocks.
3. Confirm a zero-change plan.
4. Pull and copy the state for migration.
5. Remove prod addresses from the dev state and dev addresses from the prod state using `terraform state rm`.
6. Point each root/state at its singleton map.
7. Confirm zero-change plans independently.

Do not use `terraform import` unless state copying is impossible; importing complex resources often misses dependent resource instances.

## Verification

For each environment:

```bash
terraform init -reconfigure ...backend settings...
terraform plan -var-file=dev.tfvars -detailed-exitcode
```

A successful state-only refactor should report:

```text
Plan: 0 to add, 0 to change, 0 to destroy.
```

Terraform may print address-move lines, but there must be no provider-level changes. If changes appear, restore the old resource arguments and separate any desired infrastructure updates into a later change.
